//  AppearancePicker.swift — Settings › General › Theme: Classic and Retro as pictures of the
//  real main window in each theme (App/ThemePreviews, regenerated by tools/theme-previews.sh
//  from offscreen UIShots renders), shown in the light or dark the app wears now, each with
//  its name. Mode (Auto / Light / Dark) is a plain segmented choice next to it.

import SwiftUI
import AppKit

/// A theme's preview picture, light or dark (bundled JPEGs; cached after the first load).
@MainActor
private enum ThemePreviewImage {
    private static var cache: [String: NSImage] = [:]

    static func image(_ theme: Appearance, dark: Bool) -> NSImage? {
        let name = "theme-\(theme.rawValue)-\(dark ? "dark" : "light")"
        if let hit = cache[name] { return hit }
        guard let url = Bundle.main.url(forResource: name, withExtension: "jpg"),
              let img = NSImage(contentsOf: url) else { return nil }
        cache[name] = img
        return img
    }
}

/// Settings › General › Theme: each theme as a picture of the window, with its name.
struct ThemePictureChoices: View {
    @Binding var selection: Appearance
    @Environment(\.colorScheme) private var scheme
    @Environment(\.consoleSettings) private var console
    @Environment(\.dynamicTypeSize) private var typeSize
    @ScaledLength(relativeTo: .body) private var cardWidth: CGFloat = 200

    var body: some View {
        let layout = typeSize.isAccessibilitySize
            ? AnyLayout(VStackLayout(alignment: .leading, spacing: Space.m))
            : AnyLayout(HStackLayout(alignment: .top, spacing: Space.l))
        layout {
            ForEach(Appearance.allCases) { theme in
                card(theme)
            }
        }
        .accessibilityElement(children: .contain)
        .accessibilityLabel("Theme")
    }

    private func card(_ theme: Appearance) -> some View {
        let on = theme == selection
        let ring = console ? ConsoleInk.signal : Color.accentColor
        let corner: CGFloat = 6
        return Button {
            selection = theme
        } label: {
            VStack(spacing: Space.xs) {
                Group {
                    if let img = ThemePreviewImage.image(theme, dark: scheme == .dark) {
                        Image(nsImage: img).resizable().interpolation(.high).aspectRatio(contentMode: .fill)
                    } else {
                        Rectangle().fill(.quaternary)
                    }
                }
                .frame(width: cardWidth, height: cardWidth * 0.62)
                .clipShape(RoundedRectangle(cornerRadius: corner))
                .overlay(RoundedRectangle(cornerRadius: corner).strokeBorder(Color.primary.opacity(0.15), lineWidth: 0.5))
                .shadow(color: .black.opacity(scheme == .dark ? 0.45 : 0.15), radius: 4, y: 2)
                .padding(4)
                .overlay(RoundedRectangle(cornerRadius: corner + 4).strokeBorder(on ? ring : .clear, lineWidth: 3))
                Text(theme.title)
                    .settingsText(console ? (on ? .consoleBodySmallEmphasis : .consoleBodySmall)
                                          : (on ? .calloutEmphasis : .callout))
                    .foregroundStyle(on ? .primary : .secondary)
            }
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .accessibilityLabel(theme.title)
        .accessibilityAddTraits(on ? [.isButton, .isSelected] : .isButton)
    }
}
